-- Source: Sacred_decrypted.exe @0x008EC328 (regenerate with
-- `the generator in sdk/re/py/`).
--
-- Usage:
--   local IT = require "items_gen"
--   IT.WEAPON_VAMP_SWORD_NORMAL          --> 1871
--   IT.by_id[1871].name                  --> "TYPE_WEAPON_VAMP_SWORD_NORMAL"
--   IT.by_name["TYPE_WEAPON_SWORD_VAMPIRE"].id
--   for _,e in ipairs(IT.weapons()) do ... end   -- {id,name,key,cat}
--   IT.find("VAMP_SWORD")     -- first entry whose key/name contains it
--
-- Equip an NPC with one of these (see items_equip.md for the ABI):
--   item type id -> cObjectManager::create_005fb530(om, id,0,1,0)
--                -> cCreature::equipment_equip_00555e00(creat, slot, ref, 1)
--   weapon main hand = slot 0x0D (off hand 0x0C); slot map in
--   items_equip.md (cCreature+0x1A4 + slot*4).
--
-- 5624 TYPE_* entries total; 3789 are equippable item
-- families (WEAPON/ARMOR/SHIELD/HORSEBIT).

local M = { ALL = {}, by_id = {}, by_name = {}, by_cat = {} }

local function add(id, name, key, cat)
  local e = { id = id, name = name, key = key, cat = cat }
  M.ALL[#M.ALL + 1] = e
  M.by_id[id] = e
  M.by_name[name] = e
  local b = M.by_cat[cat]; if not b then b = {}; M.by_cat[cat] = b end
  b[#b + 1] = e
  return id
end

