-- All entries of a category ("WEAPON", "ARMOR", "SHIELD", ...).
function M.of_cat(cat) return M.by_cat[cat] or {} end

-- Convenience: the equippable item families.
function M.weapons() return M.by_cat.WEAPON or {} end
function M.armor()   return M.by_cat.ARMOR  or {} end
function M.shields() return M.by_cat.SHIELD or {} end

-- First entry whose Lua key or TYPE_ name contains `sub` (case-insens).
function M.find(sub)
  sub = sub:upper()
  for _, e in ipairs(M.ALL) do
    if e.key:find(sub, 1, true) or e.name:upper():find(sub, 1, true) then
      return e
    end
  end
end

-- All entries whose key or name contains `sub` (case-insensitive).
function M.all_matching(sub)
  sub = sub:upper()
  local out = {}
  for _, e in ipairs(M.ALL) do
    if e.key:find(sub, 1, true) or e.name:upper():find(sub, 1, true) then
      out[#out + 1] = e
    end
  end
  return out
end

